class DispatchLoaderBase
{
public:
  DispatchLoaderBase() = default;
  DispatchLoaderBase( std::nullptr_t )
#if !defined( NDEBUG )
    : m_valid( false )
#endif
  {}
#if !defined( NDEBUG )
  size_t getVkHeaderVersion() const { VULKAN_HPP_ASSERT( m_valid ); return vkHeaderVersion; }
private:
  size_t vkHeaderVersion = VK_HEADER_VERSION;
  bool   m_valid         = true;
#endif
};

class DispatchLoaderDynamic : public DispatchLoaderBase
{
public:
  // Many PFN_vk* members initialized to 0
  DispatchLoaderDynamic() VULKAN_HPP_NOEXCEPT = default;
  DispatchLoaderDynamic( PFN_vkGetInstanceProcAddr getInstanceProcAddr ) VULKAN_HPP_NOEXCEPT { init( getInstanceProcAddr ); }
  DispatchLoaderDynamic( VkInstance instance, PFN_vkGetInstanceProcAddr getInstanceProcAddr, VkDevice device = {}, PFN_vkGetDeviceProcAddr getDeviceProcAddr = nullptr ) VULKAN_HPP_NOEXCEPT { init( instance, getInstanceProcAddr, device, getDeviceProcAddr ); }
  template <typename DynamicLoader> void init( DynamicLoader const & dl ) VULKAN_HPP_NOEXCEPT { PFN_vkGetInstanceProcAddr ipa = dl.template getProcAddress<PFN_vkGetInstanceProcAddr>( "vkGetInstanceProcAddr" ); init( ipa ); }
  void init( PFN_vkGetInstanceProcAddr getInstanceProcAddr ) VULKAN_HPP_NOEXCEPT { /* loads instance-level funcs */ }
  void init( VkInstance instance, PFN_vkGetInstanceProcAddr getInstanceProcAddr, VkDevice device = {}, PFN_vkGetDeviceProcAddr getDeviceProcAddr = nullptr ) VULKAN_HPP_NOEXCEPT { /* loads instance and device level funcs */ }
  void init( Instance instanceCpp ) VULKAN_HPP_NOEXCEPT { /* resolve using vkGetInstanceProcAddr */ }
  void init( Device deviceCpp ) VULKAN_HPP_NOEXCEPT { /* resolve device functions via vkGetDeviceProcAddr */ }
  template <typename DynamicLoader> void init( Instance const & instance, Device const & device, DynamicLoader const & dl ) VULKAN_HPP_NOEXCEPT { /* convenience */ }
  template <typename DynamicLoader> void init( Instance const & instance, Device const & device ) VULKAN_HPP_NOEXCEPT { /* convenience */ }
  // PFN members list continues for all supported commands
};

class DynamicLoader
{
public:
#ifdef VULKAN_HPP_NO_EXCEPTIONS
  DynamicLoader( std::string const & vulkanLibraryName = {} ) VULKAN_HPP_NOEXCEPT
#else
  DynamicLoader( std::string const & vulkanLibraryName = {} )
#endif
  {
    if ( !vulkanLibraryName.empty() ) {
#if defined( _WIN32 )
      m_library = ::LoadLibraryA( vulkanLibraryName.c_str() );
#elif defined( __unix__ ) || defined( __APPLE__ ) || defined( __QNX__ ) || defined( __Fuchsia__ )
      m_library = dlopen( vulkanLibraryName.c_str(), RTLD_NOW | RTLD_LOCAL );
#else
#  error unsupported platform
#endif
    } else {
#if defined( _WIN32 )
      m_library = ::LoadLibraryA( "vulkan-1.dll" );
#elif defined( __APPLE__ )
      m_library = dlopen( "libvulkan.dylib", RTLD_NOW | RTLD_LOCAL );
      if ( !m_library ) { m_library = dlopen( "libvulkan.1.dylib", RTLD_NOW | RTLD_LOCAL ); }
      if ( !m_library && ( std::getenv( "DYLD_FALLBACK_LIBRARY_PATH" ) == NULL ) ) { m_library = dlopen( "/usr/local/lib/libvulkan.dylib", RTLD_NOW | RTLD_LOCAL ); }
      if ( !m_library ) { m_library = dlopen( "/opt/homebrew/lib/libvulkan.dylib", RTLD_NOW | RTLD_LOCAL ); }
      if ( !m_library ) { m_library = dlopen( "libMoltenVK.dylib", RTLD_NOW | RTLD_LOCAL ); }
      if ( !m_library ) { m_library = dlopen( "vulkan.framework/vulkan", RTLD_NOW | RTLD_LOCAL ); }
      if ( !m_library ) { m_library = dlopen( "MoltenVK.framework/MoltenVK", RTLD_NOW | RTLD_LOCAL ); }
#elif defined( __unix__ ) || defined( __QNX__ ) || defined( __Fuchsia__ )
      m_library = dlopen( "libvulkan.so", RTLD_NOW | RTLD_LOCAL );
      if ( !m_library ) { m_library = dlopen( "libvulkan.so.1", RTLD_NOW | RTLD_LOCAL ); }
#else
#  error unsupported platform
#endif
    }
#ifndef VULKAN_HPP_NO_EXCEPTIONS
    if ( !m_library ) { throw std::runtime_error( "Failed to load vulkan library!" ); }
#endif
  }
  DynamicLoader( DynamicLoader const & ) = delete;
  DynamicLoader( DynamicLoader && other ) VULKAN_HPP_NOEXCEPT : m_library( other.m_library ) { other.m_library = nullptr; }
  DynamicLoader & operator=( DynamicLoader const & ) = delete;
  DynamicLoader & operator=( DynamicLoader && other ) VULKAN_HPP_NOEXCEPT { std::swap( m_library, other.m_library ); return *this; }
  ~DynamicLoader() VULKAN_HPP_NOEXCEPT
  {
    if ( m_library ) {
#if defined( __unix__ ) || defined( __APPLE__ ) || defined( __QNX__ ) || defined( __Fuchsia__ )
      dlclose( m_library );
#elif defined( _WIN32 )
      ::FreeLibrary( m_library );
#else
#  error unsupported platform
#endif
    }
  }
  template <typename T>
  T getProcAddress( const char * function ) const VULKAN_HPP_NOEXCEPT
  {
#if defined( __unix__ ) || defined( __APPLE__ ) || defined( __QNX__ ) || defined( __Fuchsia__ )
    return (T)(void *)dlsym( m_library, function );
#elif defined( _WIN32 )
    return (T)(void *)::GetProcAddress( m_library, function );
#else
#  error unsupported platform
#endif
  }
  bool success() const VULKAN_HPP_NOEXCEPT { return m_library != nullptr; }
private:
#if defined( __unix__ ) || defined( __APPLE__ ) || defined( __QNX__ ) || defined( __Fuchsia__ )
  void * m_library;
#elif defined( _WIN32 )
  ::HINSTANCE m_library;
#else
#  error unsupported platform
#endif
};

class ErrorCategoryImpl : public std::error_category
{
public:
  virtual const char * name() const VULKAN_HPP_NOEXCEPT override { return VULKAN_HPP_NAMESPACE_STRING "::Result"; }
  virtual std::string message( int ev ) const override
  {
#if defined( VULKAN_HPP_NO_TO_STRING )
    return std::to_string( ev );
#else
    return to_string( static_cast<Result>( ev ) );
#endif
  }
};

class Error
{
public:
  Error() VULKAN_HPP_NOEXCEPT = default;
  Error( const Error & ) VULKAN_HPP_NOEXCEPT = default;
  virtual ~Error() VULKAN_HPP_NOEXCEPT = default;
  virtual const char * what() const VULKAN_HPP_NOEXCEPT = 0;
};

class LogicError : public Error, public std::logic_error
{
public:
  explicit LogicError( const std::string & what ) : Error(), std::logic_error( what ) {}
  explicit LogicError( char const * what ) : Error(), std::logic_error( what ) {}
  virtual const char * what() const VULKAN_HPP_NOEXCEPT { return std::logic_error::what(); }
};

class SystemError : public Error, public std::system_error
{
public:
  SystemError( std::error_code ec ) : Error(), std::system_error( ec ) {}
  SystemError( std::error_code ec, std::string const & what ) : Error(), std::system_error( ec, what ) {}
  SystemError( std::error_code ec, char const * what ) : Error(), std::system_error( ec, what ) {}
  SystemError( int ev, std::error_category const & ecat ) : Error(), std::system_error( ev, ecat ) {}
  SystemError( int ev, std::error_category const & ecat, std::string const & what ) : Error(), std::system_error( ev, ecat, what ) {}
  SystemError( int ev, std::error_category const & ecat, char const * what ) : Error(), std::system_error( ev, ecat, what ) {}
  virtual const char * what() const VULKAN_HPP_NOEXCEPT { return std::system_error::what(); }
};

