const char *dev_type = FUZZ_GET_ATTR_STR(device, "type");
const char *slot_type = FUZZ_GET_ATTR_STR(privateDataSlot, "type");
if (!dev_type || strcmp(dev_type, "VkDevice") != 0) { FUZZ_BAIL(); }
if (!slot_type || strcmp(slot_type, "VkPrivateDataSlot") != 0) { FUZZ_BAIL(); }

// Dynamically resolve the function pointer due to VK_NO_PROTOTYPES environment
VULKAN_HPP_NAMESPACE::detail::DynamicLoader loader;
PFN_vkGetDeviceProcAddr gdpa = loader.getProcAddress<PFN_vkGetDeviceProcAddr>("vkGetDeviceProcAddr");
if (!gdpa) { FUZZ_BAIL(); }
PFN_vkDestroyPrivateDataSlot pfn = (PFN_vkDestroyPrivateDataSlot)gdpa((VkDevice)device, "vkDestroyPrivateDataSlot");
if (!pfn) { FUZZ_BAIL(); }

// Per spec, allocator must match creation; pass nullptr consistently
pfn((VkDevice)device, (VkPrivateDataSlot)privateDataSlot, nullptr);
// No outputs; slot is destroyed here

// Validate tracked handle types and metadata
const char *dev_type = FUZZ_GET_ATTR_STR(device, "type");
const char *slot_type = FUZZ_GET_ATTR_STR(privateDataSlot, "type");
if (!dev_type || strcmp(dev_type, "VkDevice") != 0) { FUZZ_BAIL(); }
if (!slot_type || strcmp(slot_type, "VkPrivateDataSlot") != 0) { FUZZ_BAIL(); }
int obj_type_enum = FUZZ_GET_ATTR_INT(object, "VkObjectType");
if (obj_type_enum <= 0) { FUZZ_BAIL(); }

// Resolve function pointer dynamically
VULKAN_HPP_NAMESPACE::detail::DynamicLoader loader;
PFN_vkGetDeviceProcAddr gdpa = loader.getProcAddress<PFN_vkGetDeviceProcAddr>("vkGetDeviceProcAddr");
if (!gdpa) { FUZZ_BAIL(); }
PFN_vkSetPrivateData pfn = (PFN_vkSetPrivateData)gdpa((VkDevice)device, "vkSetPrivateData");
if (!pfn) { FUZZ_BAIL(); }

// Use the tracked pointer bits as the handle value, as commonly done for opaque dispatchable/non-dispatchable handles in harnesses
uint64_t handle_bits = (uint64_t)(uintptr_t)object;
// Fuzz a 64-bit data payload
uint64_t data = ((uint64_t)*FUZZ_PARAM(unsigned int) << 32) | (uint64_t)*FUZZ_PARAM(unsigned int);

// Call; return value may indicate unsupported object/slot combinations; not a hard misuse
( void )pfn((VkDevice)device, (VkObjectType)obj_type_enum, handle_bits, (VkPrivateDataSlot)privateDataSlot, data );
// Persist inputs back to pool

// Validate handles
