if (!gdpa) { FUZZ_BAIL(); }
PFN_vkGetPrivateData pfn = (PFN_vkGetPrivateData)gdpa((VkDevice)device, "vkGetPrivateData");
if (!pfn) { FUZZ_BAIL(); }

